117	
118	    /**
119	     * Fixed city-to-region table used to derive an owner's locality.
120	     */
121	    java.util.Map<String, String> CITY_REGION =
122	        java.util.Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
123	
124	    /**
125	     * Inclusive 4-digit postcode range {@code [low, high]} owned by each region: NSW 2000-2099,
126	     * VIC 3000-3099, QLD 4000-4099. Used to resolve an owner's region from the postcode first.
127	     */
128	    java.util.Map<String, int[]> REGION_POSTCODES =
129	        java.util.Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
130	
131	    /**
132	     * Derives the owner's locality, the {@code REGION} segment of the owner's customer code (the
133	     * region-and-hash identity {@code '<REGION>-<HASH8>'}). Only when no customer code is present does
134	     * it fall back to deriving the region directly, preferring the postcode's {@link #REGION_POSTCODES}
135	     * range and then the fixed {@link #CITY_REGION} city table. Returns the canonical region string, or
136	     * {@code "UNKNOWN"} when neither source resolves a region.
137	     */
138	    default String locality(Owner owner) {
139	        String customerCode = owner.getCustomerCode();
140	        if (customerCode != null) {
141	            int dash = customerCode.indexOf('-');
142	            String region = dash >= 0 ? customerCode.substring(0, dash) : customerCode;
143	            if (!region.isEmpty()) {
144	                return region;
145	            }
146	        }
147	        String postcode = owner.getPostcode();
148	        if (postcode != null) {
149	            try {
150	                int value = Integer.parseInt(postcode.trim());
151	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
152	                    int[] range = entry.getValue();
153	                    if (value >= range[0] && value <= range[1]) {
154	                        return entry.getKey();
155	                    }
156	                }
157	            }
158	            catch (NumberFormatException ex) {
159	                // Not a numeric postcode; fall back to the city table below.
160	            }
161	        }
162	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
163	    }
164	
165	    /**
166	     * Fixed region-to-timezone table used to derive an owner's timezone as an IANA name.
167	     */
168	    java.util.Map<String, String> REGION_TIMEZONE =
169	        java.util.Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
170	
171	    /**
172	     * Derives the owner's timezone as an IANA name from the owner's {@link #locality(Owner) locality}
173	     * (region) via the fixed {@link #REGION_TIMEZONE} table: {@code NSW -> Australia/Sydney},
174	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}. Returns {@code null} when
175	     * the region does not resolve to a known timezone (e.g. the locality is {@code "UNKNOWN"}).
176	     */
177	    default String timezone(Owner owner) {
178	        return REGION_TIMEZONE.get(locality(owner));
179	    }
180	
181	    /**
182	     * Known E.164 country calling codes, longest first, used to split a stored E.164 telephone into
183	     * its country code and national digits when formatting {@link #telephoneDisplay(Owner)}.
184	     */
185	    String[] TELEPHONE_COUNTRY_CODES = {"61", "1"};
186	
187	    /**
188	     * Formats the owner's stored E.164 telephone for humans: the country code, a space, then the
189	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
190	     * The country code is recognised from the {@link #TELEPHONE_COUNTRY_CODES} table; when none matches,
191	     * all digits after the {@code '+'} are treated as the national number. Returns {@code null} when the
192	     * telephone is absent, and the value unchanged when it is not a {@code '+'}-prefixed E.164 number.
193	     */
194	    default String telephoneDisplay(Owner owner) {
195	        String telephone = owner.getTelephone();
196	        if (telephone == null) {
197	            return null;
198	        }
199	        if (!telephone.startsWith("+")) {
200	            return telephone;
201	        }
202	        String digits = telephone.substring(1);
203	        if (!digits.chars().allMatch(Character::isDigit)) {
204	            return telephone;
205	        }
206	        String countryCode = "";
207	        for (String code : TELEPHONE_COUNTRY_CODES) {
208	            if (digits.startsWith(code) && digits.length() > code.length()) {
209	                countryCode = code;
210	                break;
211	            }
212	        }
213	        String national = digits.substring(countryCode.length());
